import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { cpSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { basename, join, resolve } from "node:path";
import test from "node:test";

const root = resolve(process.cwd());
const targetTest = "maintainer-gate-digest-invalidation";
const staleDigest = /stale digest d0-002-prerequisites-red-census-contract-correction-renewal docs\/adr\/ADR-0001/;

const makeHistoryFreeFixture = () => {
  const parent = mkdtempSync(join(tmpdir(), "aos-history-free-acceptance-"));
  const fixture = join(parent, "repository");
  cpSync(root, fixture, {
    recursive: true,
    filter: (source) => ![".git", "node_modules"].includes(basename(source))
  });
  return { parent, fixture };
};

const run = (cwd, args) => spawnSync(process.execPath, args, {
  cwd,
  encoding: "utf8",
  timeout: 30_000,
  maxBuffer: 1024 * 1024
});

const describeResult = (result) => [
  `status=${String(result.status)}`,
  `signal=${String(result.signal)}`,
  `error=${String(result.error?.message ?? null)}`,
  `stdout=${JSON.stringify(result.stdout ?? "")}`,
  `stderr=${JSON.stringify(result.stderr ?? "")}`
].join(" ");

test("planning digest invalidation works in a history-free working copy", () => {
  const validationFixture = makeHistoryFreeFixture();
  try {
    const adr = join(validationFixture.fixture, "docs/adr/ADR-0001-product-identity-and-legacy-boundary.md");
    writeFileSync(adr, `${readFileSync(adr, "utf8")}\nMaterial semantic edit for digest invalidation.\n`);

    const validation = run(validationFixture.fixture, ["scripts/validate-planning.mjs"]);
    assert.equal(validation.error, undefined, describeResult(validation));
    assert.equal(validation.status, 1, describeResult(validation));
    assert.match(validation.stderr, staleDigest, describeResult(validation));
  } finally {
    rmSync(validationFixture.parent, { recursive: true, force: true });
  }

  const testFixture = makeHistoryFreeFixture();
  try {
    const focusedTest = run(testFixture.fixture, [
      "--test",
      `--test-name-pattern=^${targetTest}$`,
      "tests/planning-contract.test.mjs"
    ]);
    assert.equal(focusedTest.error, undefined, describeResult(focusedTest));
    assert.equal(focusedTest.status, 0, describeResult(focusedTest));
    assert.match(focusedTest.stdout, new RegExp(`ok 1 - ${targetTest}`), describeResult(focusedTest));
  } finally {
    rmSync(testFixture.parent, { recursive: true, force: true });
  }
});
